from core.rules import RuleMachine


class RepairBadTopMove:
    """Mueve un tope mal puesto a una pila donde quede bien puesto."""

    name = "repair_bad_top_move"

    def __init__(self, prefer_empty=True, avoid_breaking_sorted_sources=True):
        self.prefer_empty = prefer_empty
        self.avoid_breaking_sorted_sources = avoid_breaking_sorted_sources

    def allowed(self, partial, memory, candidates):
        if not candidates:
            return []

        stacks = partial.stacks
        h = partial.h
        G = partial.G

        def top_group(i):
            return G if h(i) == 0 else stacks[i][-1]

        def is_well_placed_at(i, grp):
            if h(i) == 0:
                return True
            return top_group(i) >= grp

        def is_bad_top_source(so):
            if h(so) == 0:
                return False
            if h(so) == 1:
                return False
            grp = stacks[so][-1]
            return stacks[so][-2] < grp

        filtered = []
        for a in candidates:
            so = a.so
            sd = a.sd
            if so == sd:
                continue
            if h(so) == 0 or h(sd) >= partial.H:
                continue
            if not is_bad_top_source(so):
                continue

            moved = stacks[so][-1]
            if not is_well_placed_at(sd, moved):
                continue

            if self.avoid_breaking_sorted_sources and partial.is_sorted_stack(so) and not partial.is_sorted_stack(sd):
                continue

            filtered.append(a)

        if not filtered:
            return []

        if self.prefer_empty:
            empty = [a for a in filtered if h(a.sd) == 0]
            if empty:
                filtered = empty

        def key(a):
            so = a.so
            sd = a.sd
            moved = stacks[so][-1]
            dest_top = top_group(sd)
            return (
                0 if h(sd) == 0 else 1,
                abs(dest_top - moved),
                h(sd),
                sd,
                so,
            )

        filtered.sort(key=key)
        return filtered


def build_component(problem, **params):
    prefer_empty = params.get("prefer_empty", COMPONENT["params"]["prefer_empty"]["default"])
    avoid_breaking_sorted_sources = params.get(
        "avoid_breaking_sorted_sources",
        COMPONENT["params"]["avoid_breaking_sorted_sources"]["default"],
    )
    return RuleMachine(
        problem,
        [RepairBadTopMove(prefer_empty=prefer_empty,
                          avoid_breaking_sorted_sources=avoid_breaking_sorted_sources)],
    )
